//! B01: `InvocationExprent`'s opcode constructor, `checkExprTypeBounds` and copy
//! against the real Vineflower 1.12.0, over every invoke instruction of
//! `data/b01/B01Calls.class` (`data/b01/GenB01Oracle.java` ->
//! `data/b01/b01_golden.txt`, regenerated by `data/b01/gen.sh`). Each
//! instruction pops from the same six typed variables, so the vectors show
//! which operand became the instance and which the parameters.

use kuna_jvm::byte_cursor::ByteCursor;
use kuna_jvm::check_types_result::ExprentTypePair;
use kuna_jvm::code_type::CodeType;
use kuna_jvm::counter_container::CounterContainer;
use kuna_jvm::decompiler_context::DecompilerContext;
use kuna_jvm::exprent::Exprent;
use kuna_jvm::invocation_exprent::InvocationExprent;
use kuna_jvm::list_stack::ListStack;
use kuna_jvm::pooled_constant::PooledConstant;
use kuna_jvm::rt::BitSet;
use kuna_jvm::struct_class::StructClass;
use kuna_jvm::struct_general_attribute::StructGeneralAttribute;
use kuna_jvm::var_exprent::VarExprent;
use kuna_jvm::var_type::VarType;

use crate::common;

const GOLDEN: &str = include_str!("data/b01/b01_golden.txt");
const CALLS: &[u8] = include_bytes!("data/b01/B01Calls.class");

fn types() -> Vec<VarType> {
    vec![
        VarType::VARTYPE_INT(),
        VarType::VARTYPE_LONG(),
        VarType::VARTYPE_STRING(),
        VarType::VARTYPE_DOUBLE(),
        VarType::VARTYPE_BOOLEAN(),
        VarType::new_value(CodeType::Object, 0, "java/util/List"),
    ]
}

fn vt(t: &VarType) -> String {
    format!(
        "{}:{}:{}",
        t.type_.name(),
        t.array_dim,
        t.value.as_deref().unwrap_or("N")
    )
}

fn var(e: Option<Exprent>) -> String {
    match e {
        None => "N".to_string(),
        Some(e) => match e.try_as_var() {
            Some(v) => format!("v{}", v.get_index()),
            None => format!("?{}", e.get_type().name()),
        },
    }
}

fn vars(es: &[Exprent]) -> String {
    if es.is_empty() {
        return "-".to_string();
    }
    es.iter()
        .map(|e| var(Some(*e)))
        .collect::<Vec<_>>()
        .join(",")
}

fn bounds(ps: &[ExprentTypePair]) -> String {
    if ps.is_empty() {
        return "-".to_string();
    }
    ps.iter()
        .map(|p| format!("{}={}", var(Some(p.exprent)), vt(&p.type_)))
        .collect::<Vec<_>>()
        .join(",")
}

fn bits(s: Option<BitSet>) -> String {
    match s {
        None => "N".to_string(),
        Some(s) if s.is_empty() => "-".to_string(),
        Some(s) => s
            .iter()
            .map(|i| i.to_string())
            .collect::<Vec<_>>()
            .join(","),
    }
}

fn args(args: &Option<Vec<Option<PooledConstant>>>) -> String {
    match args {
        None => "N".to_string(),
        Some(a) if a.is_empty() => "-".to_string(),
        Some(a) => a
            .iter()
            .map(|c| match c {
                None => "N".to_string(),
                Some(PooledConstant::Link(l)) => format!("L{}", l.index1),
                Some(c) => format!("P{}", c.type_()),
            })
            .collect::<Vec<_>>()
            .join(","),
    }
}

fn b(v: bool) -> &'static str {
    if v {
        "1"
    } else {
        "0"
    }
}

fn describe(at: &str, op: i32, e: InvocationExprent, stack_left: usize) -> Vec<String> {
    let mut out = Vec::new();
    out.push(
        [
            "inv".to_string(),
            at.to_string(),
            op.to_string(),
            e.get_id().to_string(),
            e.get_name(),
            e.get_classname(),
            b(e.is_static()).to_string(),
            e.get_functype().name().to_string(),
            e.get_invocation_type().name().to_string(),
            e.get_invoke_dynamic_class_suffix()
                .unwrap_or_else(|| "null".to_string()),
            e.get_string_descriptor(),
            vt(&e.get_expr_type()),
            var(e.get_instance()),
            vars(&e.get_lst_parameters().to_vec()),
            stack_left.to_string(),
            e.get_bootstrap_method()
                .map_or_else(|| "N".to_string(), |m| m.elementname.clone()),
            args(&e.get_bootstrap_arguments()),
            bits(e.get_bytecode()),
        ]
        .join(" "),
    );

    let r = e
        .check_expr_type_bounds()
        .expect("InvocationExprent always returns bounds");
    out.push(format!(
        "bnd {at} {} {}",
        bounds(r.get_lower_bounds()),
        bounds(r.get_upper_bounds())
    ));

    let c = e.copy().as_invocation();
    let params = c.get_lst_parameters().to_vec();
    let inst_is_p0 =
        c.get_instance().is_some() && !params.is_empty() && c.get_instance() == Some(params[0]);
    out.push(format!(
        "cpy {at} {} {} {} {} {} {} {}",
        c.get_id(),
        var(c.get_instance()),
        vars(&params),
        b(inst_is_p0),
        c.get_invoke_dynamic_class_suffix()
            .unwrap_or_else(|| "null".to_string()),
        bits(c.get_bytecode()),
        b(e.equals(c.0)),
    ));
    out
}

#[test]
fn opcode_ctor_bounds_and_copy_match_vineflower() {
    let _guard = common::install_default_context();
    let cl = StructClass::create(&mut ByteCursor::new(CALLS.to_vec()), true);
    let pool = cl.get_pool();
    let bootstrap = cl.get_attribute(StructGeneralAttribute::ATTRIBUTE_BOOTSTRAP_METHODS);

    let mut actual = Vec::new();
    for mt in cl.get_methods().to_vec() {
        mt.expand_data(cl);
        let Some(seq) = mt.get_instruction_sequence() else {
            continue;
        };
        for instr in seq.instructions() {
            let op = instr.opcode();
            if !(182..=186).contains(&op) {
                continue;
            }

            DecompilerContext::get_counter_container()
                .set_counter(CounterContainer::EXPRESSION_COUNTER, 1);
            let mut stack: ListStack<Exprent> = ListStack::new();
            for (k, t) in types().into_iter().enumerate() {
                stack.push(VarExprent::new(k as i32, Some(t), None).0);
            }

            let cn = pool
                .get_link_constant(instr.operand(0))
                .expect("invoke constant");
            let (bm, ba) = match bootstrap {
                Some(attr) if op == 186 => (
                    attr.get_method_reference(cn.index1),
                    Some(attr.get_method_arguments(cn.index1)),
                ),
                _ => (None, None),
            };
            let mut offsets = BitSet::new();
            offsets.set(instr.start_offset() as usize);

            let e = InvocationExprent::new_invoke(op, &cn, bm, ba, &mut stack, Some(&offsets));
            let at = format!("{}@{}", mt.get_name(), instr.start_offset());
            actual.extend(describe(&at, op, e, stack.size()));
        }
    }

    let expected: Vec<&str> = GOLDEN.lines().collect();
    assert!(!expected.is_empty(), "no golden lines");
    let mut mismatches = Vec::new();
    for i in 0..expected.len().max(actual.len()) {
        let e = expected.get(i).copied().unwrap_or("<missing>");
        let a = actual.get(i).map(String::as_str).unwrap_or("<missing>");
        if e != a {
            mismatches.push(format!("java: {e}\nrust: {a}"));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} mismatches\n{}",
        mismatches.len(),
        mismatches.join("\n")
    );
}
